[[nodiscard]] constexpr const MoveTable* tableFor(std::string_view game) noexcept {
    if(game=="black_nds"||game=="white_nds")return &BlackWhite;
    if(game=="black2_nds"||game=="white2_nds")return &Black2White2;
    return nullptr;
}
[[nodiscard]] constexpr bool contains(const MoveTable& table,uint16_t species,uint16_t move) noexcept {
    return species>0&&species<=MaxSpecies&&move>0&&move<=MaxMove&&
        (table[species][move/64]&(uint64_t{1}<<(move%64)))!=0;
}
[[nodiscard]] constexpr bool formAvailable(std::string_view game,uint16_t species,uint8_t form) noexcept {
    if(!tableFor(game)||species==0||species>MaxSpecies)return false;
    for(const auto& row:FormCounts)if(row.species==species)
        return form<(tableFor(game)==&BlackWhite?row.bw:row.b2w2);
    return form==0;
}
[[nodiscard]] constexpr const FormMoveRow* formRow(uint16_t species,uint8_t form) noexcept {
    for(const auto& row:FormMoves)if(row.species==species && row.form==form)return &row;
    return nullptr;
}
[[nodiscard]] constexpr bool contains(const MoveBits& row,uint16_t move) noexcept {
    return move>0&&move<=MaxMove&&(row[move/64]&(uint64_t{1}<<(move%64)))!=0;
}
[[nodiscard]] constexpr bool direct(std::string_view game,uint16_t species,uint8_t form,uint16_t move) noexcept {
    if(!formAvailable(game,species,form))return false;
    // PKHeX MoveInfo.IsSketchValid (Gen5): Smeargle can Sketch every native
    // knowable move except Struggle and Chatter; Sketch itself is level-up.
    if(species==235)return move>0 && move<=MaxMove && move!=165 && move!=448;
    const auto* t=tableFor(game);
    if(const auto* row=formRow(species,form))return contains(t==&BlackWhite?row->bw:row->b2w2,move);
    return contains(*t,species,move); // cosmetic forms share the native species learnset.
}
[[nodiscard]] constexpr bool transferable(uint16_t species,uint8_t form,uint16_t move) noexcept {
    if(direct("black_nds",species,form,move)||direct("black2_nds",species,form,move))return true;
    // Gen IV -> V Poké Transfer retains many historic moves.
    if(const auto* row=formRow(species,form))return contains(row->gen4,move);
    return species<=PokeVault::Integration::Gen4MoveCompatibility::MaxSpecies &&
        PokeVault::Integration::Gen4MoveCompatibility::anywhereInGen4(species,form,move);
}
// These freely changeable native forms retain ordinary moves learned before
// changing back. Wormadam, Rotom appliances and Kyurem fusion are NOT such a
// permission. Keep this distinct from teaching/transfer compatibility.
[[nodiscard]] constexpr bool priorForm(std::string_view game,uint16_t species,uint16_t move) noexcept {
    if(species!=386 && species!=487 && species!=492)return false;
    for(uint8_t form=0;form<4;++form)
        if(direct(game,species,form,move))return true;
    return false;
}
[[nodiscard]] constexpr Availability classify(std::string_view game,uint16_t species,uint8_t form,
                                                uint16_t move,bool inSource) noexcept {
    if(!tableFor(game)||species==0||species>MaxSpecies||move>MaxMove)return Availability::Unavailable;
    if(move==0)return Availability::Direct;
    if(formAvailable(game,species,form)) {
        if(direct(game,species,form,move))return Availability::Direct;
        if(transferable(species,form,move))return Availability::Transfer;
        if(priorForm(game,species,move))return Availability::FormHistory;
    }
    if(inSource)return Availability::Preserved;
    return Availability::Unavailable;
}
[[nodiscard]] inline std::vector<uint16_t> selectableMoves(std::string_view game,uint16_t species,
    uint8_t form,const std::array<uint16_t,4>& existingSourceMoves) {
    std::vector<uint16_t> moves{0};
    if(!tableFor(game)||species==0||species>MaxSpecies)return moves;
    for(uint16_t move=1;move<=MaxMove;move++)
        if(classify(game,species,form,move,false)!=Availability::Unavailable)moves.push_back(move);
    // Preserve already-existing unusual event/history moves WITHOUT presenting
    // them as newly legal for arbitrary Pokemon.
    for(uint16_t move:existingSourceMoves)
        if(move>0&&move<=MaxMove&&std::find(moves.begin(),moves.end(),move)==moves.end())
            moves.push_back(move);
    std::sort(moves.begin()+1,moves.end());
    return moves;
}
